WITH filtered AS (SELECT id, channel, promo_code, ends_on, discount_pct, CASE WHEN discount_pct >= 0.29 THEN 'High' WHEN discount_pct >= 0.18 THEN 'Medium' ELSE 'Low' END AS discount_pct_band, ADD_MONTHS(ends_on, 12) AS ends_on_plus_months, COALESCE(channel, 'NONE') AS channel_filled FROM promotions WHERE ends_on > DATE '2024-03-27' AND channel IS NOT NULL) SELECT *, SUM(discount_pct) OVER (ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct, RANK() OVER (ORDER BY discount_pct DESC) AS discount_pct_rank, LAG(discount_pct, 1) OVER (ORDER BY discount_pct, id) AS prev_discount_pct, SUM(discount_pct) OVER (ORDER BY ends_on_plus_months, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct_2, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on_plus_months, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct FROM filtered;
